// Anti-pattern: Manually spawning unbounded raw threads for each task
// Risks thread starvation, OutOfMemoryError under load, and lacks return values.
public class WebServer {
    public void handleRequest(final byte[] data) {
        // Spawns a raw OS thread per request!
        new Thread(new Runnable() {
            @Override
            public void run() {
                process(data);
            }
        }).start();
    }

    private void process(byte[] data) {
        // Heavy processing...
    }
}

