right_code.class:
// Modern ExecutorService: reuses bounded worker threads, supports queues & graceful shutdown
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class WebServer {
    // Bounded thread pool tuned to machine cores
    private final ExecutorService exec = Executors.newFixedThreadPool(
        Runtime.getRuntime().availableProcessors()
    );

    public void handleRequest(final byte[] data) {
        exec.execute(() -> process(data));
    }

    private void process(byte[] data) {
        // Heavy processing...
    }

    public void stop() {
        exec.shutdown();
    }
}

right_code.call_site:
public class Main {
    public static void main(String[] args) {
        WebServer server = new WebServer();
        for (int i = 0; i < 50_000; i++) {
            server.handleRequest(new byte[1024]); // Safely queued without crashing OS!
        }
        server.stop();
    }
}
